echo "== [22中.com] (66 bytes)"; ./test4_executable "$(printf '中%.0s' {1..22}).com"

cd /workspace/dataset && p63=$(printf 'a%.0s' {1..63});
echo "== [63a.63a]"; ./test4_executable "$p63.$p63";
echo "== [63a．63a] fullwidth dot"; ./test4_executable "$p63．$p63";
